import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../core/app_controller.dart';

class WalletScreen extends StatefulWidget { const WalletScreen({super.key}); @override State<WalletScreen> createState()=>_WalletScreenState(); }
class _WalletScreenState extends State<WalletScreen>{List<Map<String,dynamic>> packages=[];bool loading=true;@override void initState(){super.initState();_load();}Future<void>_load()async{final app=context.read<AppController>();try{final r=await app.api.getJson('/wallet/packages');packages=List<Map<String,dynamic>>.from((r['packages']as List).map((e)=>Map<String,dynamic>.from(e as Map)));}catch(_){}if(mounted)setState(()=>loading=false);}Future<void>_request(String id)async{final app=context.read<AppController>();try{await app.api.postJson('/wallet/recharge',{'packageId':id,'paymentMethod':'manual'});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال طلب الشحن للمراجعة.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}@override Widget build(BuildContext context){final coins=context.watch<AppController>().user?['coins']??0;return Scaffold(appBar:AppBar(title:const Text('المحفظة والشحن')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[Card(child:ListTile(leading:const Icon(Icons.account_balance_wallet_rounded),title:const Text('الرصيد'),trailing:Text('$coins 🪙',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)))),const SizedBox(height:18),const Text('باقات الشحن',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:10),...packages.map((p)=>Card(child:ListTile(title:Text(p['name'].toString()),subtitle:Text('${p['price_cents']} ${p['currency']}'),trailing:FilledButton(onPressed:()=>_request(p['id'].toString()),child:const Text('طلب شحن'))))) ]));}}
